mapper.select:
SELECT * FROM public."COM_臨時ファイル情報" WHERE "家族学生ID" = #{familyStudentId}

    AND ("元ファイル名称" ILIKE CONCAT('%',#{keyword},'%') OR COALESCE("コメント",'') ILIKE CONCAT('%',#{keyword},'%'))


    AND "MIME_TYPE" LIKE 'image/%'


    AND ("MIME_TYPE" IS NULL OR "MIME_TYPE" NOT LIKE 'image/%')


    AND "登録日時" >= #{registeredSince}


    AND "登録日時" < #{registeredBefore}

ORDER BY "登録日時" DESC, "一時ファイルID" DESC
LIMIT #{limit}

mapper.delete:
DELETE FROM public."COM_臨時ファイル情報"
 WHERE "家族学生ID" = #{familyStudentId} AND "一時ファイルID" IN
#{id}
